mapper.select:
select PAYWAY_CODE
from dt_payway
where PAYWAY_NAME = #{paywayName}

        AND PAYWAY_CODE != #{paywayCode}

select PAYWAY_CODE
from dt_payway
where PAYWAY_CODE = #{paywayCode}

        SELECT PAYWAY_CODE paywayCode, PAYWAY_NAME paywayName, SORT sort, CREATE_TIME createTime  from dt_payway


		      AND PAYWAY_NAME = #{param.paywayName}


		      AND PAYWAY_CODE = #{param.paywayCode}


		ORDER BY CREATE_TIME DESC
